<?php
namespace App\Models;
use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides member payroll assignment behavior within the WorkIntel application. */ class MemberPayrollAssignment extends Model{protected $fillable=['workspace_id','member_id','payroll_compliance_pack_id','worker_classification','tax_identifier','residency_status','exemptions','effective_from','effective_to','status'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['exemptions'=>'array','effective_from'=>DateOnly::class,'effective_to'=>DateOnly::class];}/** Handles the pack operation for the current WorkIntel workflow. */ public function pack():BelongsTo{return $this->belongsTo(PayrollCompliancePack::class,'payroll_compliance_pack_id');}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}}
